import React, { useEffect, useState } from 'react'
import useApi from '../../../../hooks/useApi'
import hospitalsApi from '../../../../api/hospitals/hospitalsApi'
import { Collapse } from 'antd'
import { Data } from '@react-google-maps/api'

export default function AdmissionRadiologyOrders({selectedAdmission}) {

     const [admissionRadiologyOrders, setadmissionRadiologyOrders] = useState([])
        
          const [data, setData] = useState([])
        
          const getAdmissionRadiologyOrdersApi = useApi(hospitalsApi.hospitalStaffAction)
          const getAdmissionRadiologyOrders = async (id) => {
            await getAdmissionRadiologyOrdersApi.request({
              "action": "GetAdmissionRadiologyOrders",
              "admission": id
            })
          }
          useEffect(() => {
            if (selectedAdmission) {
        
              getAdmissionRadiologyOrders(selectedAdmission.id)
            }
        
          }, [selectedAdmission])
          useEffect(() => {
            if (getAdmissionRadiologyOrdersApi.data) {
              if (getAdmissionRadiologyOrdersApi.data.length) {
                setadmissionRadiologyOrders(getAdmissionRadiologyOrdersApi.data)
              }
            }
        
            console.log("getAdmissionRadiologyOrdersApi.data", getAdmissionRadiologyOrdersApi.data)
          }, [getAdmissionRadiologyOrdersApi.data])
        
        
          useEffect(() => {
            if (admissionRadiologyOrders) {
              if (admissionRadiologyOrders.length) {
                setData(admissionRadiologyOrders.map((i, index) => ({
                  label: `${i.created}  ${i.destination_department_title}`,
                  key: index+1,
                  children: <div>
                    {
                      i.examinations && i.examinations.length ? <div>
        
                        {
                          i.examinations.map((y,yIn) => {
                            return <div>
                              <p className=''>
                              <span className='mx-2'>{yIn+1}.</span>
                              <span className='mx-2'>{y.examination_title}</span>
                              <span className='mx-2 font-semibold'>KES {parseFloat(y.examination_charge).toFixed(2).toString()}</span>
                              </p>
        
                            </div>
                          })
                        }
                      </div> : <div></div>
                    }
                  </div>
                })))
              }
            }
        
            console.log("getDependantRadiologyOrdersApi.data", getAdmissionRadiologyOrdersApi.data)
          }, [admissionRadiologyOrders])
  return (
    <div>
    <p className='text-2xl font-semibold text-center'>Admission Radiology Orders</p>
    {data && data.length ? <Collapse items={data} defaultActiveKey={['1']} /> : <>
      <p className='text-center'>No items retrieved</p>
      </>}
    </div>
  )
}
